const express = require('express');
const rateLimit = require('express-rate-limit');
const db = require('../db');

const app = express();
// Only trust the immediate trusted proxy hop (e.g., AWS ALB or Cloudflare)
app.set('trust proxy', 'loopback, linklocal, uniquelocal');

const exportLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  // Key rate limiting by authenticated user identity rather than spoofable IP headers
  keyGenerator: (req) => req.user?.id || req.ip,
  message: { error: 'Too many export requests' }
});

app.get('/api/v1/organizations/:orgId/payroll-export', exportLimiter, async (req, res) => {
  const { orgId } = req.params;

  // Verify caller belongs to the targeted organization and holds payroll permissions
  if (req.user.organizationId !== orgId || req.user.role !== 'payroll_admin') {
    return res.status(403).json({ error: 'Forbidden: Access denied to organization payroll' });
  }

  const records = await db('payroll_records').where({ organization_id: orgId });
  if (!records || records.length === 0) {
    return res.status(404).json({ error: 'No payroll records found' });
  }

  return res.json({ organizationId: orgId, payroll: records });
});

module.exports = app;
